import { chromium } from 'playwright';import fs from 'fs';import path from 'path';
const BASE='https://www.statesideqm.com',THEME='158900125851',label=process.env.LABEL,route=process.env.ROUTE,group=process.env.GROUP,OUT='sep18-single-route-'+process.env.KEY;fs.mkdirSync(path.join(OUT,'screenshots'),{recursive:true});
const u=new URL(route,BASE);u.searchParams.set('preview_theme_id',THEME);const b=await chromium.launch({headless:true});const c=await b.newContext({viewport:{width:1440,height:1000}});await c.addInitScript(()=>{window.__sqLcp=0;try{new PerformanceObserver(l=>{for(const e of l.getEntries())window.__sqLcp=Math.max(window.__sqLcp,e.startTime||0)}).observe({type:'largest-contentful-paint',buffered:true})}catch{}});const p=await c.newPage();p.setDefaultNavigationTimeout(70000);const req=[];p.on('request',r=>{if(r.resourceType()==='fetch'||r.resourceType()==='xhr')req.push(r.url())});let response=null,error=null;try{response=await p.goto(u.href,{waitUntil:'domcontentloaded',timeout:70000});await p.waitForLoadState('load',{timeout:16000}).catch(()=>{});await p.waitForTimeout(1200)}catch(e){error=String(e?.message||e)}
const row=await p.evaluate(({label,route,group,req,themeId})=>{const n=performance.getEntriesByType('navigation')[0],rs=performance.getEntriesByType('resource'),f=performance.getEntriesByName('first-contentful-paint')[0],grid=document.querySelector('[data-testid="product-grid"]');return{label,route,group,theme:{id:String(window.Shopify?.theme?.id||''),name:String(window.Shopify?.theme?.name||'')},ttfbMs:Math.round(n?.responseStart||0),dclMs:Math.round(n?.domContentLoadedEventEnd||0),loadMs:Math.round(n?.loadEventEnd||0),fcpMs:Math.round(f?.startTime||0),lcpMs:Math.round(window.__sqLcp||0),resources:rs.length,transferBytes:rs.reduce((s,r)=>s+(r.transferSize||0),0),domNodes:document.getElementsByTagName('*').length,styles:document.querySelectorAll('style').length,scripts:document.scripts.length,images:document.images.length,cards:grid?.querySelectorAll('.product-grid__item').length||0,lastPage:grid?.dataset.lastPage||'',brokenImages:[...document.images].filter(i=>i.complete&&i.naturalWidth===0).length,stateGuardRoot:document.querySelectorAll('[data-sq-state-guard-root]').length,rail:document.querySelectorAll('[data-sq-collection-rail]').length,page2Section:req.filter(u=>u.includes('section_id=')&&/[?&]page=2(?:&|$)/.test(u)).length,h1:(document.querySelector('h1')?.textContent||'').replace(/\s+/g,' ').trim(),previewOk:String(window.Shopify?.theme?.id||'')===themeId}}, {label,route,group,req,themeId:THEME});row.httpStatus=response?.status()??null;row.error=error;fs.writeFileSync(OUT+'/result.json',JSON.stringify(row,null,2));await p.screenshot({path:path.join(OUT,'screenshots','result.png'),fullPage:false}).catch(()=>{});console.log('SINGLEROUTE',JSON.stringify({...row,transferKB:Math.round((row.transferBytes||0)/1024)}));if(row.httpStatus!==200||!row.previewOk||error)process.exitCode=2;await c.close();await b.close();